<?php

declare(strict_types=1);

require_once __DIR__.'/Database.php';
require_once __DIR__.'/Auth.php';
require_once __DIR__.'/AccessPolicy.php';
require_once __DIR__.'/AppNavigation.php';
require_once __DIR__.'/ProductionContext.php';
require_once __DIR__.'/LatePickupService.php';

final class LatePickupExperience
{
    private const ROUTE='/production/late-pickups';
    public static function handles(string $route):bool{return$route===self::ROUTE;}
    public static function render(string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user||!AccessPolicy::canManageProduction($user)){http_response_code(403);exit('Production management permission is required.');}$_SESSION['late_pickup_csrf']??=bin2hex(random_bytes(24));$production=ProductionContext::selected($db,$user);if(!$production)self::redirect($basePath.'/production');if($_SERVER['REQUEST_METHOD']==='POST')self::post($db,$user,$production,$basePath);self::page($db,$user,$production,$basePath);
    }
    private static function post(PDO $db,array $user,array $production,string $basePath):never
    {
        if(!hash_equals((string)$_SESSION['late_pickup_csrf'],(string)($_POST['csrf_token']??''))){self::flash('error','Your session expired.');self::redirect($basePath.self::ROUTE);}try{$db->beginTransaction();$action=(string)($_POST['action']??'');$productionId=(int)$production['id'];$actor=(int)$user['id'];if($action==='settings')LatePickupService::saveSettings($db,$productionId,$actor,(int)($_POST['occurrence_threshold']??3),(int)($_POST['grace_minutes']??10),(string)($_POST['notice_template']??''));elseif($action==='save_draft'||$action==='submit_draft')LatePickupService::saveDraft($db,$productionId,(int)($_POST['notice_id']??0),$actor,(string)($_POST['subject']??''),(string)($_POST['body']??''),$action==='submit_draft');elseif($action==='approve')LatePickupService::approve($db,$productionId,(int)($_POST['notice_id']??0),$actor);elseif($action==='send'){$queued=LatePickupService::send($db,$productionId,(int)($_POST['notice_id']??0),$actor);self::flash('success',$queued.' guardian email'.($queued===1?'':'s').' queued. Queued does not mean delivered.');}elseif($action==='resolve'||$action==='dismiss')LatePickupService::resolve($db,$productionId,(int)($_POST['review_id']??0),$actor,$action==='resolve'?'resolved':'dismissed',(string)($_POST['resolution_reason']??''));else throw new RuntimeException('Choose a valid late pickup action.');$db->commit();if($action!=='send')self::flash('success','Late pickup workflow updated.');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();self::flash('error',$e instanceof RuntimeException?$e->getMessage():'The late pickup update could not be saved.');}self::redirect($basePath.self::ROUTE);
    }
    private static function page(PDO $db,array $user,array $production,string $basePath):never
    {
        // Late arrival is a separate operational measure from late pickup.
        // Show recorded Late attendance within the selected production, including
        // calls still in planning. Do not infer pickup lateness from arrival state.
        $arrivalStmt=$db->prepare("SELECT ar.user_id,CONCAT(u.first_name,' ',u.last_name) student_name,COUNT(*) occurrence_count,MAX(si.starts_at) last_call_at FROM attendance_records ar JOIN schedule_items si ON si.id=ar.schedule_item_id AND si.production_id=:production AND si.status='active' JOIN users u ON u.id=ar.user_id WHERE ar.status='late' AND EXISTS(SELECT 1 FROM production_memberships pm WHERE pm.user_id=ar.user_id AND pm.production_id=si.production_id AND pm.audience_type='student') GROUP BY ar.user_id,u.first_name,u.last_name ORDER BY occurrence_count DESC,student_name");
        $arrivalStmt->execute(['production'=>(int)$production['id']]);
        $lateArrivals=$arrivalStmt->fetchAll();
        $settings=LatePickupService::settings($db,(int)$production['id']);$reviews=LatePickupService::dashboard($db,(int)$production['id']);$u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(?string $v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$flash=$_SESSION['late_pickup_flash']??null;unset($_SESSION['late_pickup_flash']);header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Late review · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/late-pickups.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar(self::ROUTE,$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Production','Late',$basePath,AppNavigation::productionSubnav(self::ROUTE,$user));?><div class="lp-page"><?php if($flash):?><div class="lp-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><header class="lp-hero"><div><small><?=$e(strtoupper((string)$production['title']))?> · STAFF REVIEW</small><h2>Late arrivals & pickups</h2><p>Review late arrival attendance separately from late pickup occurrences. Pickup review uses actual checkout and the configured grace period; an arrival marked Late does not create a pickup violation.</p></div><a href="<?=$u('/attendance')?>">Attendance</a></header>
        <section class="lp-list lp-arrivals"><header><div><small>ATTENDANCE</small><h3>Late arrivals</h3></div><span><?=count($lateArrivals)?> students</span></header><?php if(!$lateArrivals):?><div class="lp-empty">No late arrivals recorded for this production.</div><?php else:foreach($lateArrivals as $arrival):?><div class="lp-arrival-row"><strong><?=$e((string)$arrival['student_name'])?></strong><span><?=(int)$arrival['occurrence_count']?> late arrival<?=((int)$arrival['occurrence_count']===1?'':'s')?></span><small>Most recent call: <?=$e(date('M j, Y',strtotime((string)$arrival['last_call_at'])))?></small></div><?php endforeach;endif;?></section>
        <h3 class="lp-section-title">Late pickup review & guardian notices</h3>
        <details class="lp-settings"><summary><span><b>Review settings</b><small>Threshold <?=(int)$settings['occurrence_threshold']?> · <?=(int)$settings['grace_minutes']?> minute grace</small></span><strong>Edit</strong></summary><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['late_pickup_csrf'])?>"><input type="hidden" name="action" value="settings"><label>Occurrences before review<input type="number" min="1" max="20" name="occurrence_threshold" value="<?=(int)$settings['occurrence_threshold']?>" required></label><label>Grace minutes after scheduled end<input type="number" min="0" max="120" name="grace_minutes" value="<?=(int)$settings['grace_minutes']?>" required></label><label class="wide">Optional default notice wording<textarea name="notice_template" maxlength="5000" rows="5" placeholder="Leave blank for the neutral CTSMD template."><?=$e($settings['notice_template'])?></textarea></label><p class="wide">Preview: a student is flagged when non-reversed late checkouts reach <?=(int)$settings['occurrence_threshold']?>. A draft is created; nothing is sent automatically.</p><button class="button">Save settings and recompute</button></form></details>
        <section class="lp-list"><header><div><small>ACTION ITEMS</small><h3>Students requiring review</h3></div><span><?=count($reviews)?> tracked</span></header><?php if(!$reviews):?><div class="lp-empty">No student has crossed this production's configured threshold.</div><?php endif;?><?php foreach($reviews as $review):$noticeStatus=(string)($review['notice_status']??'none');?><details class="lp-row"><summary><span><b><?=$e($review['student_name'])?></b><small><?=(int)$review['occurrence_count']?> occurrence<?=((int)$review['occurrence_count']===1?'':'s')?> · threshold <?=(int)$review['threshold_at_open']?></small></span><em class="status-<?=$e((string)$review['status'])?>"><?=$e(ucwords(str_replace('_',' ',(string)$review['status'])))?></em><em class="notice-<?=$e($noticeStatus)?>"><?=$e(ucwords(str_replace('_',' ',$noticeStatus)))?></em><strong>Review</strong></summary><div class="lp-drawer"><section><h4>Occurrence history</h4><?php foreach($review['occurrences'] as $occurrence):?><article class="lp-occurrence <?=$occurrence['voided_at']?'is-void':''?>"><span><b><?=$e(date('M j, Y',strtotime((string)$occurrence['starts_at'])))?> · <?=$e($occurrence['title'])?></b><small>Pickup about <?=$e(date('g:i A',strtotime((string)$occurrence['actual_checkout_at'])))?> · expected <?=$e(date('g:i A',strtotime((string)$occurrence['expected_release_at'])))?> · <?=(int)$occurrence['late_minutes']?> minutes</small></span><?php if($occurrence['voided_at']):?><em>Reversed · <?=$e($occurrence['void_reason'])?></em><?php endif;?></article><?php endforeach;?></section><section><h4>Current guardian eligibility</h4><?php if(!$review['guardians']):?><p class="lp-warning">No current active guardian has an eligible email address. Approval and sending are blocked.</p><?php else:foreach($review['guardians'] as $guardian):?><p><?=$e($guardian['name'])?> · <?=$e($guardian['email'])?></p><?php endforeach;endif;?></section><?php if($review['notice_id']):?><form method="post" class="lp-notice"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['late_pickup_csrf'])?>"><input type="hidden" name="notice_id" value="<?=(int)$review['notice_id']?>"><label>Subject<input name="subject" maxlength="255" value="<?=$e($review['subject'])?>" required></label><label>Guardian notice<textarea name="body" rows="10" maxlength="8000" required><?=$e($review['body'])?></textarea></label><p>Revision <?=(int)$review['revision_number']?>. Edit and submit for approval, then approve, then explicitly send. Queued does not prove delivery.</p><div class="lp-actions"><?php if(in_array($noticeStatus,['draft','pending_approval','approved'],true)):?><button name="action" value="save_draft">Save draft</button><button name="action" value="submit_draft">Submit for approval</button><?php endif;?><?php if($noticeStatus==='pending_approval'):?><button class="button" name="action" value="approve"<?=$review['guardians']?'':' disabled'?>>Approve final content</button><?php endif;?><?php if($noticeStatus==='approved'):?><button class="button" name="action" value="send"<?=$review['guardians']?'':' disabled'?>>Send to current guardians</button><?php endif;?></div></form><?php if($review["notice_revisions"]):?><details class="lp-history"><summary>Notice revision history</summary><?php foreach($review["notice_revisions"] as $revision):?><p><b>Revision <?=(int)$revision["revision_number"]?></b> · <?=$e(date("M j · g:i A",strtotime((string)$revision["created_at"])))?> · <?=$e($revision["subject"])?></p><?php endforeach;?></details><?php endif;?><?php if($review["recipients"]):?><div class="lp-delivery"><h4>Recipient queue history</h4><?php foreach($review["recipients"] as $recipient):?><p><b><?=$e($recipient["recipient_name"])?></b> · <?=$e($recipient["recipient_email"])?> · <?=$e(ucfirst((string)$recipient["queue_status"]))?><?php if($recipient["queue_status"]==="queued"):?> (delivery not confirmed)<?php endif;?></p><?php endforeach;?></div><?php endif;?><?php endif;?><form method="post" class="lp-resolve"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['late_pickup_csrf'])?>"><input type="hidden" name="review_id" value="<?=(int)$review['id']?>"><label>Resolution reason<input name="resolution_reason" maxlength="1000" required></label><div><button name="action" value="dismiss">Dismiss</button><button name="action" value="resolve">Resolve</button></div></form></div></details><?php endforeach;?></section></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
    private static function flash(string $type,string $message):void{$_SESSION['late_pickup_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}
